import { tags } from "typia";

/**
 * Avatar image response containing the user's custom avatar URI and a flag indicating whether the default placeholder is being used.
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IAvatarImageResponse = {
  /**
   * URI string pointing to the user's avatar image file for download and display.
   *
   * @x-autobe-specification Query hrms_files where owner_id=userId and file_category='user_avatar' and validation_status='validated' and deleted_at=null. Return storage_path as URI. If no custom avatar exists, return default placeholder URI.
   */
  avatar_uri:
    | (string & tags.Format<"uri"> & tags.ContentMediaType<"image/png">)
    | (string & tags.Format<"uri"> & tags.ContentMediaType<"image/jpeg">);

  /**
   * Flag indicating whether the default placeholder avatar is being used instead of a custom one.
   *
   * @x-autobe-specification Boolean true if no custom avatar exists in hrms_files for the specified user. Boolean false if custom avatar was found and returned in avatar_uri.
   */
  default_avatar: boolean;
};
